def algorithm(func, dim, lb, ub, budget, rng):
    def clip(candidate, lb, ub):
        return np.clip(candidate, lb, ub)

    best_solution = None
    best_fitness = float('inf')

    for _ in range(budget // 10):
        population = np.random.uniform(lb, ub, size=(10, dim))

        for _ in range(budget // 100):
            new_population = np.zeros((10, dim))

            for i in range(10):
                candidate = clip(population[i] + rng.normal(size=dim), lb, ub)

                u1 = rng.choice(range(10))
                u2 = (u1 - 1) % 10
                v1 = rng.choice(range(dim))
                v2 = rng.choice(range(dim))

                new_population[i] = candidate.copy()
                new_population[i][v1], new_population[i][v2] = population[u1][v1] + rng.normal(), population[u2][v2] + rng.normal()

            population[:] = clip(new_population, lb, ub)

            for i in range(10):
                fitness = func(population[i])

                if fitness < best_fitness:
                    best_solution = population[i].copy()
                    best_fitness = fitness

    return best_solution
